insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'plant', 'planting', 'زراعة درنات البطاطا', 'ازرع درنات سليمة على عمق 8–10 سم تقريبًا، ويمكن تقطيع الدرنات الكبيرة بشرط أن تحتوي كل قطعة على عين أو أكثر.', 0, null, null, '{}'::int[], 1) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'water', 'irrigation', 'متابعة ري البطاطا', 'افحص رطوبة التربة بإصبعك على عمق 3–5 سم واروِ عند جفافها فقط. تجاوز المهمة إذا هطلت أمطار كافية أو كانت التربة رطبة؛ فالحاجة الفعلية تتأثر بنوع التربة والطقس وعمر النبات.', 7, 5, 115, '{}'::int[], 2) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'hill-1', 'care', 'التحضين الأول (تكويم التراب)', 'كوّم التراب حول السيقان لحماية الدرنات من الضوء الذي يسبب اخضرارها.', 30, null, null, '{}'::int[], 3) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'hill-2', 'care', 'التحضين الثاني', 'أعد تكويم التراب، خاصة إذا ظهرت درنات قرب السطح.', 50, null, null, '{}'::int[], 4) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'fert', 'fertilizing', 'تسميد البطاطا', 'تسميد معتدل قبل مرحلة تكوّن الدرنات، مع الري بعده.', 35, null, null, '{}'::int[], 5) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'pests', 'pest_check', 'فحص البطاطا من الأمراض', 'راقب ظهور بقع داكنة على الأوراق (اللفحة) خاصة في الطقس الرطب، وأزل النباتات المصابة بشدة.', 21, 10, 115, '{}'::int[], 6) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'harvest', 'harvest', 'بداية فترة حصاد البطاطا المتوقعة', 'يحين الحصاد عادة عند اصفرار المجموع الخضري وجفافه. أوقف الري قبل الحصاد بأيام ليسهل القلع.', 90, null, null, '{}'::int[], 7) on conflict (crop_id, key) do nothing;
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'overview', 'نظرة عامة', 'البطاطا محصول درني يفضّل الأجواء المعتدلة. الحرارة الشديدة تضعف تكوّن الدرنات، والصقيع يتلف المجموع الخضري.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'planting', 'الزراعة', 'تُزرع من درنات تقاوي سليمة. في الساحل تُزرع غالبًا في الشتاء والخريف، وفي المرتفعات في الربيع، وفي الأغوار في الشتاء.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'care', 'العناية', 'التحضين (تكويم التراب) أهم عملية؛ فهو يحمي الدرنات من الضوء والحشرات ويزيد المساحة المتاحة لتكوّنها.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'irrigation', 'الري', 'حافظ على رطوبة متوسطة منتظمة، خاصة بعد الإزهار. الغمر يسبب تعفن الدرنات، والعطش يسبب تشوهها.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'fertilization', 'التسميد', 'سماد عضوي جيد التحلل عند التجهيز، وتسميد معتدل قبل تكوّن الدرنات.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'harvest', 'الحصاد', 'بعد 90–120 يومًا تقريبًا عند ذبول الأوراق. احصد في يوم جاف وخزّن الدرنات في مكان مظلم ومهوّى.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'problems', 'المشكلات الشائعة', 'اللفحة المتأخرة في الطقس الرطب، وفراشة درنات البطاطا، واخضرار الدرنات عند تعرضها للضوء.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'problems');
insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation) values ('onion', 'البصل', array['البصل الأخضر','البصل الأحمر','البصل الأبيض']::text[], 'Allium cepa', 'bulb', 'annual', 'easy', 'full_sun', 'moderate', false, array['home_garden','rooftop','balcony','containers','small_plot','farm']::text[], 100, 150, 'تقريبًا من الشتل حتى نضج الأبصال الجافة. البصل الأخضر يُقطف أبكر بكثير.', 'محصول شتوي سهل، يُزرع بالأشتال أو بالبصيلات الصغيرة، ويمكن قطفه أخضر أو تركه حتى تجف أبصاله.', 'ري معتدل منتظم، ويُخفف قرب النضج.', 'أبصال بصل طازجة', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.', array['transplanting']::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end;
