insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'overview', 'نظرة عامة', 'الخس نبات ورقي يحب الجو المعتدل والبارد. في الحر يتجه للإزهار (الحنبلة) وتصبح أوراقه مُرّة.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'planting', 'الزراعة', 'يُزرع بالبذر أو بالأشتال. في الساحل يُزرع طوال الموسم البارد، وفي المرتفعات في الربيع والخريف.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'planting');
