insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'fertilization', 'التسميد', 'تسميد خفيف يكفي؛ الإفراط في الآزوت قد يرفع تراكم النترات في الأوراق.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'fertilization');
