insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'fertilization', 'التسميد', 'تسميد معتدل قبل الإزهار وخلال الإثمار.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'harvest', 'الحصاد', 'يمتد القطف عدة أسابيع أو أشهر حسب الصنف والطقس.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'harvest');
