insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation) values ('grape', 'العنب', array['الدوالي','الكرمة','ورق العنب','العريشة']::text[], 'Vitis vinifera', 'tree', 'perennial', 'medium', 'full_sun', 'low', false, array['home_garden','rooftop','small_plot','farm']::text[], null, null, 'كرمة معمّرة؛ يبدأ الإنتاج عادةً بعد سنتين إلى ثلاث من الزراعة حسب الصنف والعناية.', 'الدالية جزء من البيت الشامي، ويمكن تربيتها على عريشة فوق السطح أو الساحة. تشتهر الخليل بكرومها.', 'الكرمة الصغيرة تحتاج إلى ري صيفي، والكرمة الكبيرة تتحمل الجفاف نسبيًا.', 'عنقود عنب ناضج', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.', array['saplings']::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end;
