insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'grape'), 'hole', 'soil_prep', 'تجهيز جورة الكرمة', 'جورة واسعة جيدة الصرف مع سماد عضوي متحلل، وتجهيز دعامة أو عريشة.', -14, null, null, '{}'::int[], 0) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'grape'), 'plant', 'planting', 'زراعة غرسة العنب', 'ازرع الغرسة وثبّتها على الدعامة، واروِ بعد الزراعة.', 0, null, null, '{}'::int[], 1) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'grape'), 'water', 'irrigation', 'ري الكرمة الصغيرة', 'افحص رطوبة التربة بإصبعك على عمق 3–5 سم واروِ عند جفافها فقط. تجاوز المهمة إذا هطلت أمطار كافية أو كانت التربة رطبة؛ فالحاجة الفعلية تتأثر بنوع التربة والطقس وعمر النبات.', 14, 7, 365, array[5,6,7,8,9,10]::int[], 2) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'grape'), 'train', 'care', 'توجيه الساق على الدعامة', 'اختر ساقًا قوية واربطها على الدعامة لتكوين الجذع.', 60, null, null, '{}'::int[], 3) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'grape'), 'pests', 'pest_check', 'فحص الكرمة', 'راقب البياض الدقيقي (غبار أبيض على الأوراق) والبياض الزغبي في الطقس الرطب.', 30, 14, 365, '{}'::int[], 4) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'grape'), 'fert', 'fertilizing', 'تسميد خفيف للكرمة', 'سماد عضوي خفيف حول الغرسة.', 75, null, null, '{}'::int[], 5) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'grape'), 'prune', 'care', 'التقليم الشتوي الأول', 'يتم التقليم في فترة السكون الشتوي؛ يُنصح بالتعلم من مزارع خبير أو مرشد زراعي.', 330, null, null, '{}'::int[], 6) on conflict (crop_id, key) do nothing;
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'overview', 'نظرة عامة', 'العنب كرمة معمّرة متساقطة الأوراق، تحب الشمس والصيف الجاف، وتحتاج إلى برودة الشتاء في كثير من الأصناف.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'planting', 'الزراعة', 'تُزرع الغراس في فترة السكون الشتوي، مع دعامة أو عريشة قوية.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'care', 'العناية', 'التقليم الشتوي هو أهم عملية لتحديد الإنتاج وشكل الكرمة. وجّه الأفرع على العريشة خلال الربيع.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'irrigation', 'الري', 'الكرمة الحديثة تحتاج إلى ري صيفي منتظم، أما الكبيرة فتتحمل الجفاف لكن الري المعتدل يحسن الإنتاج.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'fertilization', 'التسميد', 'سماد عضوي في الشتاء، وتسميد معتدل في الربيع.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'harvest', 'الحصاد', 'يقطف العنب عند اكتمال اللون والحلاوة، ويختلف الموعد كثيرًا بين الأصناف والمناطق.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'problems', 'المشكلات الشائعة', 'البياض الدقيقي، والبياض الزغبي، وحشرات البق الدقيقي، وتعفن العناقيد في الرطوبة.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'problems');
