insert into public.faqs (question, answer, sort_order) select 'هل استخدام رزنامة الزراعة الذكية مجاني؟', 'نعم، جميع المزايا الأساسية متاحة مجانًا: دليل المحاصيل، ومولّد الخطط، والرزنامة، وإدارة المهام. قد نضيف مستقبلًا مزايا متقدمة اختيارية دون المساس بالنسخة الأساسية.', 0 where not exists (select 1 from public.faqs where question = 'هل استخدام رزنامة الزراعة الذكية مجاني؟');
insert into public.faqs (question, answer, sort_order) select 'هل مواعيد الزراعة في المنصة دقيقة لمنطقتي؟', 'المواعيد الحالية تقديرات أولية عامة مبنية على المناطق المناخية في بلاد الشام (ساحلي، جبلي، سهلي، غور، صحراوي). نوضح ذلك في كل صفحة، وننصح دائمًا بمراجعة الإرشاد الزراعي المحلي لأن الصنف والتربة والارتفاع تؤثر كثيرًا.', 1 where not exists (select 1 from public.faqs where question = 'هل مواعيد الزراعة في المنصة دقيقة لمنطقتي؟');
insert into public.faqs (question, answer, sort_order) select 'هل أحتاج إلى حساب لإنشاء خطة زراعية؟', 'لا. يمكنك إنشاء خطة وتجربتها مباشرة، وتُحفظ في متصفحك على هذا الجهاز فقط. عند إنشاء حساب تُحفظ خططك ومهامك في قاعدة البيانات وتجدها من أي جهاز، ويمكنك نقل بياناتك المحلية إلى حسابك.', 2 where not exists (select 1 from public.faqs where question = 'هل أحتاج إلى حساب لإنشاء خطة زراعية؟');
insert into public.faqs (question, answer, sort_order) select 'من أين تأتي بيانات الطقس؟', 'نعرض توقعات الطقس من خدمة Open-Meteo المفتوحة لعدة أيام قادمة فقط، مع ذكر المصدر ووقت التحديث. لا نعرض توقعات لأشهر قادمة لأنها غير متوفرة بدقة كافية.', 3 where not exists (select 1 from public.faqs where question = 'من أين تأتي بيانات الطقس؟');
insert into public.faqs (question, answer, sort_order) select 'هل تخبرني المنصة متى أروي نباتاتي بالضبط؟', 'نقترح مواعيد لمتابعة الري ونذكّرك بها، لكن الحاجة الفعلية للري تعتمد على رطوبة التربة ونوعها وعمر النبات والطقس. لذلك ننصح بفحص التربة قبل الري، ولا نعتمد على درجة الحرارة وحدها.', 4 where not exists (select 1 from public.faqs where question = 'هل تخبرني المنصة متى أروي نباتاتي بالضبط؟');
insert into public.faqs (question, answer, sort_order) select 'هل يمكنني تعديل المهام المقترحة؟', 'نعم. يمكنك تعديل تاريخ أي مهمة أو وصفها، ووضعها كمكتملة أو تأجيلها أو حذفها، وإضافة مهامك الخاصة وربطها بمحاصيلك.', 5 where not exists (select 1 from public.faqs where question = 'هل يمكنني تعديل المهام المقترحة؟');
insert into public.faqs (question, answer, sort_order) select 'هل تصلني تذكيرات على البريد أو الهاتف؟', 'حاليًا تظهر التذكيرات داخل المنصة للمهام القريبة والمتأخرة. البنية جاهزة لإضافة البريد الإلكتروني والإشعارات الفورية لاحقًا، ولن نفعّلها قبل ربط خدمة حقيقية واختبارها.', 6 where not exists (select 1 from public.faqs where question = 'هل تصلني تذكيرات على البريد أو الهاتف؟');
insert into public.site_settings (key, value) values ('weather_thresholds', '{"frostTempC":2,"heatTempC":35,"rainProbabilityPct":60,"heavyRainMm":20,"strongWindKmh":40}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('contact', '{"email": ""}'::jsonb) on conflict (key) do nothing;
